        or not 0 <= at <= 10 ** 9
    ):
        fail(EXIT_INPUT, "INPUT")
    now = parse_warm_now(raw_op["now"])
    return ("cy", base, base_at, config, at, now)

if name == "ct":
    # 配置指纹查询：精确键序仅 op，只读且不推进时钟。
